"""Exercise 1.2 - variance.

Implement `variance(xs)`: the POPULATION variance (divide by n, not n-1) of a non-empty list.
Raise ValueError on an empty list. You may reuse exercise 1.1.
"""


def variance(xs):
    if not xs:
        raise ValueError("empty list")
    m = sum(xs) / len(xs)
    return sum((x - m) ** 2 for x in xs) / (len(xs) - 1)
